/// Kết quả một mục kiểm.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Ok,
    /// Chạy được nhưng nên xử lý (hoặc đang chờ, ví dụ OHS đang index).
    Warn,
    /// Hỏng: `pkm` sẽ không chạy đúng.
    Fail,
