    /// Suy trạng thái từ payload `status` của một tiến trình đã `ready`. `eta_s` luôn `None` ở đây.
    ///
    /// Thứ tự kiểm (theo hành vi đo được ở OHS 0.17.2-vantt.1):
    /// 1. `model` (model đã dựng index) khác `active_model`: `model_missing`.
    /// 2. `indexing_errors` có lỗi `operation: "initialize"` (index ngừng hẳn): `model_missing` nếu lỗi nói tới
    ///    model, huggingface hay onnx; ngược lại `broken`.
    /// 3. `language_pack.loaded` = false (có `OHS_LANGUAGE_PACK` mà gói không nạp được; OHS vẫn chạy nhưng tìm
    ///    không có xử lý tiếng Việt): `broken`.
    /// 4. `pending` > 0: `indexing`.
    /// 5. `total` = 0 và `model` = null (chưa nhúng note nào): `starting`.
    /// 6. Còn lại: `ready`. `failed_indexing` > 0 không chặn: note lỗi được ghi lại và thử lại ở lần index sau, các
    ///    note khác vẫn tìm được. Điều kiện `indexed + notes_without_chunks == total` luôn đúng (OHS tính
    ///    `notes_without_chunks` = `total - indexed`), nên `pending` = 0 là tín hiệu index xong.
    pub fn from_status(status: &Value) -> Self {
        let num = |k: &str| status.get(k).and_then(Value::as_u64).unwrap_or(0);
        let model = status.get("model").and_then(Value::as_str);
        let active = status.get("active_model").and_then(Value::as_str);
        if let (Some(model), Some(active)) = (model, active)
            && model != active
        {
            return Self::ModelMissing {
                detail: format!("index dựng bằng {model}, OHS đang dùng {active}"),
            };
        }
        let init_error = status
            .get("indexing_errors")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .find(|e| e.get("operation").and_then(Value::as_str) == Some("initialize"))
            .map(|e| {
                e.get("message")
                    .and_then(Value::as_str)
                    .unwrap_or("không rõ lỗi")
            });
        if let Some(message) = init_error {
            let lower = message.to_lowercase();
            return if ["model", "huggingface", "onnx"]
                .iter()
                .any(|k| lower.contains(k))
            {
                Self::ModelMissing {
                    detail: message.to_owned(),
                }
            } else {
                Self::Broken {
                    action: format!(
                        "OHS không dựng được index: {message}. Sửa nguyên nhân (quyền ghi, dung lượng đĩa) rồi khởi \
                         động lại pkm."
                    ),
                }
            };
        }
        if let Some(pack) = status.get("language_pack")
            && pack.get("loaded").and_then(Value::as_bool) == Some(false)
            "giữ nguyên mục `{OHS_SERVER_NAME}` bạn tự thêm; `{SERVER_NAME}` đã có search và read nên có thể bỏ \
             `{OHS_SERVER_NAME}` (không bắt buộc; để cả hai thì agent thấy hai tool search và OHS nạp model hai lần)"
        )
    })
}

/// Mô tả việc làm ấm index OHS (cho `--dry-run`).
fn warm_plan(args: &InstallArgs) -> String {
    if args.no_ohs {
        "không làm ấm index tìm kiếm (--no-ohs)".to_owned()
    } else if args.no_warm {
        "không làm ấm index tìm kiếm (--no-warm)".to_owned()
    } else {
        "làm ấm index tìm kiếm của OHS (chạy OHS tới khi index xong, tối đa 30 phút)".to_owned()
    }
}

/// Làm ấm index tìm kiếm của OHS sau khi cài. Không bao giờ làm lệnh cài thất bại: `pkm` vẫn chạy khi index chưa
/// xong (`search` báo `ohs_not_ready` tới lúc đó).
fn warm(
    inst: &Install,
    args: &InstallArgs,
    vault: &Path,
    hooks: &dyn Hooks,
    out: &mut dyn Write,
) -> Result<(), String> {
    let w = |out: &mut dyn Write, s: String| writeln!(out, "{s}").map_err(|e| e.to_string());
    if args.no_ohs {
        return Ok(());
    }
    if args.no_warm {
        return w(
            out,
            "bỏ qua làm ấm index tìm kiếm (--no-warm); OHS sẽ index lần đầu khi Claude Desktop mở pkm".to_owned(),
        );
    }
    // Gói dùng chung chỉ ra bằng `--ohs DIR`, không thì gói cài ở thư mục của pkm.
    let dir = args.ohs.clone().unwrap_or_else(|| inst.ohs_dir());
    let Ok(pkg) = OhsPackage::from_dir(&dir) else {
        return Ok(());
    };
    w(
        out,
        format!(
            "làm ấm index tìm kiếm của OHS cho {} (lần đầu có thể mất vài phút; Ctrl+C để bỏ, OHS sẽ index tiếp khi \
             Claude Desktop mở pkm)…",
            vault.display()
        ),
    )?;
    let state = hooks.warm_ohs(pkg, vault, WARM_TIMEOUT, out);
    if state.is_ready() {
        w(out, "index tìm kiếm sẵn sàng".to_owned())
    } else {
        w(
            out,
            format!(
                "cảnh báo: index tìm kiếm chưa xong ({}): {} `{SERVER_NAME}` vẫn chạy; search báo ohs_not_ready tới \
                 khi xong",
                state.name(),
                state.action()
            ),
        )
    }
}

