enum Phase {
    /// Đang khởi động hoặc chờ khởi động lại; có tiến trình khi đã spawn.
    Starting(Option<Arc<Proc>>),
    /// Đã `ready`: nhận request.
    Running(Arc<Proc>),
    /// Không khởi động lại nữa; chuỗi là `action`.
    Broken(String),
