        match hooks.check_db(&db) {
            Ok(detail) => return Check::ok(ID, detail),
            Err(e) => e,
        }
    } else {
        format!("{} chưa có", db.display())
    };
    Check::bad(ID, Status::Fail, detail, action).with_fix(fixes.rebuild(&db))
}

