785:             "material" => material_cmd(&a),
786:             "zones" => zones_cmd(&a),
787:             _ => pairs_cmd(&a),
788:         };
789:         match result {
790:             Ok(()) => ExitCode::SUCCESS,
791:             Err(Failure::Message(m)) => fail(&format!("{}: {m}", a.cmd)),
792:             Err(Failure::Exit(code, m)) => {
793:                 eprintln!("{m}");
794:                 ExitCode::from(code)
795:             }
796:         }
