814:     fn ohs_failure(cmd: &str, e: &OhsError) -> Failure {
815:         let v = e
816:             .not_ready_error()
817:             .unwrap_or_else(|| json!({"error": "ohs_error", "detail": e.to_string()}));
818:         if let Err(f) = print_json(&v) {
819:             return f;
