824:     /// Index graph sẵn để đọc: build tăng dần với gói, adapter, cách đọc của lần build trước (trừ `--no-refresh`).
825:     fn graph(a: &Args) -> Result<Graph, Failure> {
826:         let db =
827:             a.db.clone()
828:                 .unwrap_or_else(|| a.vault.join(".kg").join("graph.db"));
829:         if !db.exists() {
830:             return Err(Failure::Message(format!(
831:                 "chưa có index graph ở {}: dựng trước bằng pkm VAULT build (bản B: --adapter e11 --packs capture \
832:                  --no-aliases --edge-keys links --body-edges)",
833:                 db.display()
834:             )));
835:         }
836:         if !a.no_refresh {
837:             let spec = index::previous(&db, "adapter_spec", "");
838:             let adapter = adapter::load(&spec)?;
839:             let packs = index::previous(&db, "packs", "");
840:             index::build(
841:                 &a.vault,
842:                 &db,
843:                 &Build {
844:                     packs: packs
845:                         .split(',')
846:                         .filter(|p| !p.is_empty())
847:                         .map(str::to_owned)
848:                         .collect(),
849:                     opts: Options::pick(false, None, false, Some(&db)),
850:                     adapter: adapter.as_deref(),
851:                     ..Build::default()
852:                 },
853:             )?;
854:         }
855:         Ok(Graph::open(&db)?)
856:     }
