858:     fn material_cmd(a: &Args) -> Result<(), Failure> {
859:         let [raw] = &a.args[..] else {
860:             return Err(Failure::Message(
861:                 "cần đúng một bản nháp (pkm VAULT material \"Bài viết/X\")".into(),
862:             ));
863:         };
864:         let draft =
865:             material::resolve_draft(&a.vault, raw).map_err(|e| Failure::Exit(1, e.to_string()))?;
866:         let extra = match &a.hits {
867:             Some(f) => {
868:                 let text = std::fs::read_to_string(f).map_err(|e| {
869:                     Failure::Message(format!("không đọc được {}: {e}", f.display()))
870:                 })?;
871:                 let v: Value = serde_json::from_str(&text).map_err(|e| {
872:                     Failure::Message(format!("{} không phải JSON: {e}", f.display()))
873:                 })?;
874:                 material::hits_from_value(&v).map_err(Failure::Message)?
875:             }
876:             None => Vec::new(),
877:         };
878:         let g = graph(a)?;
879:         let o = material::Options {
880:             k: a.k.unwrap_or(material::Options::default().k),
881:             per_query: a.per_query,
882:         };
883:         // OHS chỉ chạy khi bản nháp có chữ để tìm.
884:         let needs_ohs = !material::draft_queries(&a.vault, &draft)
885:             .map_err(|e| Failure::Message(e.to_string()))?
886:             .is_empty();
887:         let ohs = needs_ohs.then(|| launch(a));
888:         let search = |q: &str, limit: usize| match &ohs {
889:             Some(o) => material::ohs_search(o, q, limit),
890:             None => Ok(Vec::new()),
891:         };
892:         let r = material::gather(&g, &a.vault, &draft, &o, &extra, &search);
893:         drop(ohs);
894:         match r {
895:             Ok(v) => print_json(&v),
896:             Err(material::Error::Ohs(e)) => Err(ohs_failure("material", &e)),
897:             Err(e) => Err(Failure::Message(e.to_string())),
898:         }
899:     }
