901:     /// Vector note từ OHS, đã lọc; OHS tắt ngay sau khi lấy xong.
902:     fn note_vectors(a: &Args, cmd: &str, min_words: usize) -> Result<pairs::NoteVectors, Failure> {
903:         let ohs = launch(a);
904:         let r = pairs::fetch(&ohs, &a.vault, min_words);
905:         drop(ohs);
906:         match r {
907:             Ok(v) => Ok(v),
908:             Err(pairs::FetchError::Ohs(e)) => Err(ohs_failure(cmd, &e)),
909:             Err(pairs::FetchError::Other(m)) => Err(Failure::Message(m)),
910:         }
911:     }
912: 
913:     /// Ghi `text` vào `path`, tạo thư mục cha.
914:     fn write_file(path: &Path, text: &str) -> Result<(), Failure> {
915:         if let Some(dir) = path.parent() {
916:             std::fs::create_dir_all(dir)?;
917:         }
918:         std::fs::write(path, text)
919:             .map_err(|e| Failure::Message(format!("không ghi được {}: {e}", path.display())))
920:     }
