922:     fn pairs_cmd(a: &Args) -> Result<(), Failure> {
923:         let o = PairOptions {
924:             min: a.min,
925:             max: a.max,
926:             per_note: a.per_note,
927:             min_words: a.min_words.unwrap_or(PairOptions::default().min_words),
928:         };
929:         let v = note_vectors(a, "pairs", o.min_words)?;
930:         let p = pairs::similar_pairs(&v, &o);
931:         let picked = p.picked.len();
932:         let list = Value::Array(p.picked);
933:         let out = a.out.clone().or_else(|| {
934:             a.write
935:                 .then(|| a.vault.join("_E11").join("similar-pairs.json"))
936:         });
937:         if let Some(path) = &out {
938:             write_file(path, &pyjson::dumps(&list, pyjson::INDENT1))?;
939:         }
940:         eprintln!(
