    fn pkm_entry(&self) -> Result<ServerEntry, String> {
        let mut read = self.preset.mcp_flags.clone();
        if let Some(dir) = &self.args.ohs {
            let pkg = OhsPackage::from_dir(dir).map_err(|e| format!("--ohs: {e}"))?;
