            format!("{id} {name}").into_bytes()
        };
        files.push((name.to_owned(), files::sha256_hex(&body)));
        served.push((name.to_owned(), body));
    }
    let p = PinnedPlugin {
        id: id.to_owned(),
        repo: format!("owner/{id}"),
        version: version.to_owned(),
        files,
    };
    let served = served
        .into_iter()
        .map(|(name, body)| (p.url(&name), body))
        .collect();
    (p, served)
